    "tools.brightness.powerOn": "Display einschalten",
    "tools.brightness.ddcNote": "Ein externes Display auszuschalten ist weder Schlaf noch Spiegelung. Wie bei Lunar wird das Panel von WindowServer getrennt, damit macOS es nicht mehr ansteuert; USB und Laden bleiben aktiv. Antwortet der Monitor noch per DDC, gehen Hintergrundbeleuchtung und Kontrast zuerst auf 0. Einschalten verbindet ihn wieder und stellt die vorherigen Werte her.",
    "tools.brightness.axTitle": "Bedienungshilfen-Berechtigung nötig",
    "tools.brightness.axBody": "Die echte Hintergrundbeleuchtung des internen Displays läuft über das macOS-Kontrollzentrum. Erlaube SayKnow Kit in Systemeinstellungen → Datenschutz & Sicherheit → Bedienungshilfen. Steht es dort schon, entferne den Eintrag und füge ihn neu hinzu.",
    "tools.brightness.axTranslocated": "Die App läuft aus einer isolierten temporären Kopie, deshalb verwirft macOS die Berechtigung. Verschiebe SayKnow Kit nach „Programme“, führe xattr -dr com.apple.quarantine \"/Applications/SayKnow Kit.app\" aus und öffne sie erneut.",
    "tools.brightness.axGrant": "Berechtigung anfordern",
    "tools.brightness.axRestart": "App neu starten",
    "tools.brightness.axAdhoc": "Dieser Build ist ad hoc signiert, macOS bindet die Berechtigung also an genau diese Binärdatei. Nach einem Update bleibt der Eintrag aktiviert, wird aber verweigert. Führe tccutil reset Accessibility com.sayknow.app aus, erlaube es erneut und starte die App neu.",
